'use server'

import { revalidatePath } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/lib/preferences'

export async function toggleNotifications() {
  const current = await getNotificationPreference()
  await setNotificationPreference(!current)

  // Purge the cached data for this route so the current page re-renders
  // with the updated preference. Unlike redirect(), this keeps the user
  // on the same page — the router refreshes it in place.
  revalidatePath('/')
}

